import { createElement } from '../../../shared/dom-manipulation';
export function renderCalendar() {
    const date = new Date();
    const day = date.getDate();
    return createElement('div', {
        attrs: {
            class: 'neon-app-nav-icon-calendar-wrapper'
        }
    }, createElement('neon-2_20_1-icon', {
        attrs: {
            'data-icon': 'app-nav-calendar',
            class: 'neon-app-nav-icon-calendar'
        }
    }), createElement('span', {
        text: day.toString(),
        attrs: {
            'aria-hidden': 'true',
            class: 'neon-app-nav-icon-calendar-date'
        }
    }));
}
